\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}

\title{Efficiency of a Solar Water Heater\\Under Partly Cloudy Conditions}
\author{J.~Binder\\Physics 242 Lab, Section C}
\date{May 2026}

\begin{document}
\maketitle
\tableofcontents

\section{Introduction}
A flat-plate collector converts sunlight to hot water with an
efficiency that depends on irradiance, wind, and inlet temperature.
This experiment measures the efficiency of the rooftop collector on the
lab building across six clear-to-cloudy days.

\section{Apparatus}
The collector is a single-glazed flat plate with an area of two square
meters.
A thermocouple pair reads inlet and outlet temperature, and a turbine
meter reads flow.
A pyranometer on the same rail logs irradiance once per minute.

\section{Procedure}
Water circulates through the collector from 10:00 to 14:00 each day.
We record inlet temperature, outlet temperature, flow, and irradiance,
then compute efficiency in ten-minute bins.
Days with less than four hours of usable data are dropped.

\section{Results}
Measured efficiency ranges from 34 percent on the cloudiest day to 58
percent on the clearest day.
Efficiency falls off fastest when wind exceeds six meters per second.

\section{Conclusion}
The collector meets its rated efficiency on clear days and degrades
predictably under cloud and wind.
A wind shield on the north edge is the cheapest plausible improvement.

\end{document}

